# Optional: python3 mutants.py FROM TO runs only that slice (the Mac session stops long runs).
if len(sys.argv) == 3: M = M[int(sys.argv[1]):int(sys.argv[2])]
survived = 0
for target, name, old, new in M:
    src = SRC[target]
    if src.count(old) != 1:
        print('SETUP PROBLEM  %s (found %d times)' % (name, src.count(old))); survived += 1; continue
    d = tempfile.mkdtemp()
    os.makedirs(os.path.join(d, 'stage3'))
    for f in FILES:
        open(os.path.join(d, f), 'w', encoding='utf8').write(src.replace(old, new) if f == target else SRC[f])
    env = dict(os.environ, ES256=os.path.join(d, 'es256.js'), PUSH=os.path.join(d, 'push.js'), HUB=os.path.join(d, 'hub.js'), ROWPUSH=os.path.join(d, 'rowpush.js'), SW=os.path.join(d, 'stage3/sw.js'), PAGE=os.path.join(d, 'stage3/index.html'), LOCK=os.path.join(d, 'lock.js'), ENGINE=os.path.join(d, 'engine.js'), SETUP=os.path.join(d, 'setup.js'), PHONETAB=os.path.join(d, 'phonetab.js'), SETUPTAB=os.path.join(d, 'setuptab.js'), MENU=os.path.join(d, 'menu.js'))
    try:
        out = subprocess.run(['node', '--test'] + [os.path.join(here, t) for t in TESTS], env=env,
                             capture_output=True, text=True, timeout=180).stdout
        fails = re.findall(r'^not ok \d+ - (.*)$', out, re.M)
    except subprocess.TimeoutExpired:
        fails = ['(hung - counted as caught)']
    shutil.rmtree(d, ignore_errors=True)
    if fails: print('caught    %-40s by %d test(s): %s' % (name, len(fails), fails[0][:60]))
    else: print('SURVIVED  %s' % name); survived += 1
print('\n%d mutants, %d survived' % (len(M), survived)); sys.exit(1 if survived else 0)
